				"count": 10,
				"fontSize": "small",
				"headerVisibility": "fixed",
				"tableFormat": {
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5"
				}
			},
			"title": "ISE Failure Reasons",
			"type": "splunk.table"
		},
		"viz_dns_trend_chart": {
			"dataSources": {
				"primary": "ds_ise_by_nas"
			},
			"description": "Authentication pass/fail breakdown by Network Access Server",
			"options": {
				"backgroundColor": "#131a23",
				"count": 10,
				"fontSize": "small",
				"headerVisibility": "fixed",
				"tableFormat": {
					"headerBackgroundColor": "#1c2738",
					"headerColor": "#ecf0f5"
