				"majorFontSize": 36,
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"showTrendIndicator": false,
				"sparklineDisplay": "off"
			},
			"title": "Cloud FW Blocked",
			"type": "splunk.singlevalue"
		},
		"viz_events_table": {
			"context": {
				"Unique_SourcesColumnFormatEditorConfig": {
					"number": {
						"thousandSeparated": true,
						"unitPosition": "after"
					}
				},
				"Unique_TargetsColumnFormatEditorConfig": {
					"number": {
						"thousandSeparated": true,
						"unitPosition": "after"
					}
				}
			},
			"dataSources": {
