				"columnFormat": {
					"Unique Sources": {
						"align": "auto",
						"data": "> table | seriesByName(\"Unique Sources\") | formatByType(Unique_SourcesColumnFormatEditorConfig)",
						"headerAlign": "auto",
						"textOverflow": "break-word"
					},
					"Unique Targets": {
						"align": "auto",
						"data": "> table | seriesByName(\"Unique Targets\") | formatByType(Unique_TargetsColumnFormatEditorConfig)",
