	"dataSources": {
		"ds_base_fw_ref": {
			"name": "Security Resilience - Base Firewall Search",
			"options": {
				"query": "`index_firewall` (sourcetype=\"cisco:asa\" OR sourcetype=\"cisco:ftd\" OR sourcetype=\"cisco:sfw:estreamer\")\n| fields _time, _raw",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_base_psirt": {
			"name": "Security Resilience - PSIRT",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:securityadvisory\" \n| eval AdvisorySeverity=upper(AdvisorySir)\n| eval severity_rank=case(AdvisorySeverity==\"CRITICAL\",4, AdvisorySeverity==\"HIGH\",3, AdvisorySeverity==\"MEDIUM\",2, AdvisorySeverity==\"LOW\",1, 1==1,0)\n| stats latest(AdvisorySeverity) as AdvisorySeverity, max(severity_rank) as severity_rank, dc(DeviceName) as affected_devices by AdvisoryID\n| sort -severity_rank, -affected_devices\n| table AdvisoryID AdvisorySeverity affected_devices",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_cloud_fw_blocked": {
			"name": "Security Resilience - Cloud Firewall Blocked Connections",
			"options": {
				"query": "`index_security` sourcetype=\"cisco:cloud_security:firewall\" action=\"Blocked\"\n| stats count by src, dest, dest_port\n| stats count as count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_email_threats_trend": {
			"name": "Email Threats Trend",
			"options": {
				"query": "`index_security` (sourcetype=\"cisco:esa:amp\" OR sourcetype=\"cisco:esa:antispam\" OR sourcetype=\"cisco:esa:content_scanner\") ((MALICIOUS OR Unscannable) OR (SPAM OR SUSPECT OR POSITIVE OR quarantine) OR (virus OR malware OR DETECTED)) | timechart fixedrange=false count as \"Email Threats\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_failed_detail_sources": {
			"name": "Security Resilience - Failed Detail Sources",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Authentication where Authentication.action=\"failure\" Authentication.src!=\"\" Authentication.src!=\"-\" Authentication.src!=\"::1\" Authentication.src!=\"127.0.0.1\" sourcetype=\"*WinEventLog\" BY Authentication.src\n| rename Authentication.src as \"Source IP\", count as Failures\n| sort -Failures\n| head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_failed_detail_users": {
			"name": "Security Resilience - Failed Detail Users",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Authentication where Authentication.action=\"failure\" sourcetype=\"*WinEventLog\" BY Authentication.user\n| rename Authentication.user as User, count as Failures\n| where NOT match(User, \"\\$$\")\n| sort -Failures\n| head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_failed_logons_trend": {
			"name": "Failed Logons Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` dc(Authentication.user) as count from datamodel=Authentication where Authentication.action=\"failure\" by _time | timechart fixedrange=false sum(count) as \"Failed (ISE+AD)\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_fw_allowed_trend": {
			"name": "Firewall Allowed Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Network_Traffic where All_Traffic.action=\"allowed\" by _time \n| timechart sum(count) as \"Allowed\" fixedrange=false ",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_fw_blocked_trend": {
			"name": "Firewall Blocked Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Network_Traffic where All_Traffic.action=\"blocked\" by _time \n| timechart sum(count) as \"Blocked\" fixedrange=false",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_fw_top_blocked": {
			"name": "Security Resilience - Top Blocked Firewall Sources",
			"options": {
				"query": "| tstats `scd_summariesonly` count as blocked_connections from datamodel=Network_Traffic where All_Traffic.action=\"blocked\" by All_Traffic.dest\n| rename All_Traffic.dest as \"Destination IP\", blocked_connections as \"Blocked Connections\"\n| where isnotnull('Destination IP')\n| sort -\"Blocked Connections\"\n| head 10",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_fw_trend": {
			"name": "Firewall Trend",
			"options": {
				"extend": "ds_base_fw_ref",
				"query": "| eval fw_action=case(match(_raw,\"(?i)(deny|denied|block|drop)\"),\"Blocked\", 1==1,\"Allowed\") \n| timechart count by fw_action"
			},
			"type": "ds.chain"
		},
		"ds_identity_detail_trend": {
			"name": "Security Resilience - Identity Detail Trend",
			"options": {
				"query": "(`index_windows` sourcetype=\"*WinEventLog\" (EventCode=4624 OR EventCode=4625 OR EventCode=4740)) OR (`index_identity` sourcetype=\"cisco:ise:syslog\" (\"5200\" OR \"5400\"))\n| eval evt=case(EventCode==4624,\"AD_Success\", EventCode==4625,\"AD_Failed\", EventCode==4740,\"AD_Lockout\", match(_raw,\"5200\"),\"ISE_Success\", match(_raw,\"5400\"),\"ISE_Failed\", 1==1,\"Other\")\n| where evt!=\"Other\"\n| timechart count by evt",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_identity_trend": {
			"name": "Security Resilience - Identity Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Authentication BY _time Authentication.action, sourcetype\n| rename Authentication.action as action\n| eval evt=case( action==\"success\" AND sourcetype==\"cisco:ise:syslog\",\"ISE_Pass\", action==\"failure\" AND sourcetype==\"cisco:ise:syslog\",\"ISE_Fail\", action==\"success\",\"AD_Success\", action==\"failure\",\"AD_Failure\", action==\"lockout\",\"Lockout\", 1==1,\"Other\")\n| timechart count by evt",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ids_trend": {
			"name": "IDS IPS Alerts Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` count FROM datamodel=Cisco_Security WHERE nodename=Secure_Firewall_Dataset.Intrusion_Events by _time \n| timechart fixedrange=false sum(count) as \"IDS/IPS Alerts\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ise_auth": {
			"name": "Security Resilience - ISE Auth",
			"options": {
				"query": "`index_identity` sourcetype=\"cisco:ise:syslog\" (\"5200\" OR \"5401\")\n| eval passed=if(match(_raw,\"5200\"),1,0)\n| stats sum(passed) as pass, count as total\n| eval score=if(total>0, round(pass/total*100, 1), 0)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ise_by_nas": {
			"name": "Security Resilience - ISE by NAS",
			"options": {
				"query": "`index_identity` sourcetype=\"cisco:ise:syslog\" (\"5200\" OR \"5401\")\n| rex \"NetworkDeviceName=(?<nas>[^,;]+)\"\n| fillnull nas value=\"Unknown\"\n| eval passed=if(match(_raw,\"5200\"),1,0)\n| stats count as Total, sum(passed) as Pass by nas\n| eval Fail=Total-Pass, \"Pass %\"=round(Pass/Total*100, 1)\n| sort -Total\n| head 10\n| rename nas as \"Network Access Server\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ise_fail_trend": {
			"name": "ISE Failures Trend",
			"options": {
				"query": "`index_identity` sourcetype=\"cisco:ise:syslog\" \"5401\" | timechart fixedrange=false count as \"ISE Failures\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ise_failure_reasons": {
			"name": "Security Resilience - ISE Failure Reasons",
			"options": {
				"query": "`index_identity` sourcetype=\"cisco:ise:syslog\" \"5401\"\n| rex \"FailureReason=(?<reason>[^,;]+)\"\n| fillnull reason value=\"Unknown\"\n| stats count by reason\n| sort -count\n| head 10\n| rename reason as \"Failure Reason\", count as Count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_ise_trend": {
			"name": "ISE Auth Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Authentication where sourcetype=\"cisco:ise:syslog\" BY _time Authentication.action \n| rename Authentication.action as result \n| where result IN (\"success\",\"failure\") \n| timechart fixedrange=false sum(count) as count by result",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_kpi_email": {
			"name": "KPI Email Threats",
			"options": {
				"extend": "ds_email_threats_trend",
				"query": "| fields _time \"Email Threats\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_failed": {
			"name": "KPI Failed Logons",
			"options": {
				"extend": "ds_failed_logons_trend",
				"query": "| fields _time \"Failed (ISE+AD)\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_fw_allowed": {
			"name": "KPI Firewall Allowed",
			"options": {
				"extend": "ds_fw_allowed_trend",
				"query": "| fields _time \"Allowed\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_fw_blocked": {
			"name": "KPI Firewall Blocked",
			"options": {
				"extend": "ds_fw_blocked_trend",
				"query": "| fields _time \"Blocked\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_ids": {
			"name": "KPI IDS IPS Alerts",
			"options": {
				"extend": "ds_ids_trend",
				"query": "| fields _time \"IDS/IPS Alerts\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_ise_fail": {
			"name": "KPI ISE Failures",
			"options": {
				"extend": "ds_ise_fail_trend",
				"query": "| fields _time \"ISE Failures\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_lockouts": {
			"name": "KPI Lockouts",
			"options": {
				"extend": "ds_lockouts_trend",
				"query": "| fields _time \"Lockouts (AD)\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_privileged": {
			"name": "KPI Privileged Logons",
			"options": {
				"extend": "ds_privileged_trend",
				"query": "| fields _time \"Privileged (AD)\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_rogue": {
			"name": "KPI Rogue Devices",
			"options": {
				"extend": "ds_rogue_trend",
				"query": "| fields _time \"Rogue Devices\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_sdwan": {
			"name": "KPI SD-WAN UTD",
			"options": {
				"extend": "ds_sdwan_utd_trend",
				"query": "| fields _time \"SD-WAN UTD\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_unauth": {
			"name": "KPI Unauthorized Wireless",
			"options": {
				"extend": "ds_unauth_wireless_trend",
				"query": "| fields _time \"Unauth Wireless\""
			},
			"type": "ds.chain"
		},
		"ds_kpi_web": {
			"name": "KPI Web Blocked",
			"options": {
				"extend": "ds_web_threats_trend",
				"query": "| fields _time \"Web Blocked\""
			},
			"type": "ds.chain"
		},
		"ds_lockout_detail": {
			"name": "Security Resilience - Lockout Detail",
			"options": {
				"query": "`index_windows` sourcetype=\"*WinEventLog\" EventCode=4740\n| stats count as Lockouts, latest(_time) as last_seen, values(TargetDomainName) as sources by TargetUserName\n| eval last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M\"), sources=mvjoin(sources, \", \")\n| sort -Lockouts\n| head 10\n| rename TargetUserName as \"Locked User\", sources as \"Source Hosts\", last_seen as \"Last Lockout\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_lockouts_trend": {
			"name": "Lockouts Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` dc(Authentication.user) as count from datamodel=Authentication where Authentication.action=\"lockout\" by _time | timechart fixedrange=false sum(count) as \"Lockouts (AD)\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_priv_detail": {
			"name": "Security Resilience - Privileged Logon Detail",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Authentication where Authentication.signature_id=4672 sourcetype=\"*WinEventLog\" BY Authentication.user\n| rename Authentication.user as User, count as \"Priv Logons\"\n| sort -\"Priv Logons\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_priv_trend": {
			"name": "Privileged Logon Trend",
			"options": {
				"query": "`index_windows` sourcetype=\"*WinEventLog\" EventCode=4672\n| timechart fixedrange=false dc(user) as \"Privileged Users\", count as \"Logon Events\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_privileged_trend": {
			"name": "Privileged Logons Trend",
			"options": {
				"query": "| tstats `scd_summariesonly` count from datamodel=Authentication where (Authentication.signature_id=4672 OR Authentication.signature_id=4673) sourcetype=\"*WinEventLog\" by _time | timechart fixedrange=false sum(count) as \"Privileged (AD)\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_psirt_count": {
			"name": "Security Advisories",
			"options": {
				"extend": "ds_base_psirt",
				"query": "| stats count as advisories"
			},
			"type": "ds.chain"
		},
		"ds_rogue_device_detail": {
			"name": "Security Resilience - Rogue Device Detail",
			"options": {
				"query": "(`index_network` sourcetype=\"cisco:ios\" (\"%SISF-4-MAC_STEAL\" OR \"%DOT1X-5-FAIL\" OR \"Rogue\")) OR (`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueName=\"*rogue*\")\n| eval event_type=case(match(_raw,\"%SISF-4-MAC_STEAL\"),\"MAC Steal\", match(_raw,\"%DOT1X-5-FAIL\"),\"802.1X Failure\", match(_raw,\"(?i)rogue\") AND sourcetype==\"cisco:dnac:issue\",\"DNAC Rogue Alert\", match(_raw,\"(?i)rogue\"),\"Rogue Detected\", 1==1,\"Other\")\n| eval device=coalesce(host, DeviceName, \"unknown\")\n| stats count as events, latest(_time) as last_seen by device, event_type\n| eval last_seen=strftime(last_seen, \"%Y-%m-%d %H:%M:%S\")\n| sort -events\n| rename device as \"Device\", event_type as \"Event Type\", events as \"Events\", last_seen as \"Last Seen\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_rogue_trend": {
			"name": "Rogue Devices Trend",
			"options": {
				"query": "(`index_network` sourcetype=\"cisco:ios\" (\"%SISF-4-MAC_STEAL\" OR \"%DOT1X-5-FAIL\" OR \"Rogue\")) OR (`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueName=\"*rogue*\") | timechart fixedrange=false count as \"Rogue Devices\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_sdwan_utd_trend": {
			"name": "SD-WAN UTD Trend",
			"options": {
				"query": "`index_security` sourcetype=\"cisco:sdwan:utd:logs\" \n| rex field=_raw \"\\]\\s+(?<utd_action>\\w+)\\s+\\[\\*\\*\\]\\s+UTD\" \n| where utd_action=\"Drop\" OR utd_action=\"Block\" \n| timechart fixedrange=false count as \"SD-WAN UTD\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_security_events": {
			"name": "Security Resilience - Security Events",
			"options": {
				"query": "(`index_firewall` sourcetype=\"cisco:asa\" (\"Deny\" OR \"denied\" OR \"Teardown\")) OR (`index_identity` sourcetype=\"cisco:ise:syslog\" \"5400\") OR (`index_security` (sourcetype=\"cisco:cloud_security:dns\" OR sourcetype=\"cisco:cloud_security:firewall\") action=\"Blocked\") OR (`index_firewall` (sourcetype=\"cisco:estreamer:data\" OR sourcetype=\"cisco:sfw:estreamer\")) OR (`index_catalyst` sourcetype=\"cisco:dnac:audit:logs\" name=\"LOGIN_USER_EVENT\") OR (`index_windows` sourcetype=\"*WinEventLog\" (EventCode=4625 OR EventCode=4740 OR EventCode=4672))\n| eval Source=case(sourcetype==\"cisco:asa\",\"ASA\", sourcetype==\"cisco:ise:syslog\",\"ISE\", match(sourcetype,\"estreamer\"),\"Firepower\", match(sourcetype,\"cloud_security:dns\"),\"Umbrella DNS\", match(sourcetype,\"cloud_security:firewall\"),\"Umbrella FW\", match(sourcetype,\"dnac:audit\"),\"DNAC\", sourcetype==\"XmlWinEventLog\",\"Active Directory\", 1==1,sourcetype)\n| eval Event=case(sourcetype==\"cisco:asa\" AND match(_raw,\"(?i)deny\"),\"Firewall Deny\", sourcetype==\"cisco:asa\" AND match(_raw,\"(?i)teardown\"),\"Connection Teardown\", sourcetype==\"cisco:ise:syslog\",\"Authentication Failure\", match(sourcetype,\"estreamer\"),\"Intrusion Event\", match(sourcetype,\"cloud_security:dns\"),\"DNS Blocked\", match(sourcetype,\"cloud_security:firewall\"),\"Web Blocked\", match(sourcetype,\"dnac:audit\"),\"Login Attempt\", EventCode==4625,\"Logon Failed\", EventCode==4740,\"Account Lockout\", EventCode==4672,\"Privileged Logon\", 1==1,\"Security Event\")\n| eval Severity=case(match(_raw,\"(?i)(crit|emerg|alert)\"),\"Critical\", match(_raw,\"(?i)(err|deny|denied|block|5400)\") OR EventCode==4625 OR EventCode==4740,\"High\", match(_raw,\"(?i)(warn)\") OR EventCode==4672,\"Medium\", 1==1,\"Low\")\n| eval src=coalesce(src_ip, src, Source_Network_Address, \"—\"), dest=coalesce(dest_ip, dest, dst, Target_Server_Name, \"—\")\n| stats count as Count, latest(_time) as _time, values(src) as \"Source IP\", values(dest) as Destination by Source, Event, Severity\n| eval Time=strftime(_time, \"%Y-%m-%d %H:%M:%S\"), \"Source IP\"=mvindex('Source IP', 0, 4), Destination=mvindex(Destination, 0, 4)\n| sort -_time\n| table Time Source Event Severity \"Source IP\" Destination Count",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_unauth_wireless_trend": {
			"name": "Unauthorized Wireless Trend",
			"options": {
				"query": "(`index_network` sourcetype=\"cisco:ios\" (\"%DOT11-4-MAXRETRIES\" OR \"%LWAPP-3-\" OR \"Rogue AP\")) OR (`index_catalyst` sourcetype=\"cisco:dnac:client\" 'connection.authType'=\"Open\") | timechart fixedrange=false count as \"Unauth Wireless\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_web_threats_trend": {
			"name": "Web Blocked Trend",
			"options": {
				"query": "`index_security` (sourcetype=\"cisco:wsa:squid\" OR sourcetype=\"cisco:wsa:l4tm\") | timechart fixedrange=false count(eval(match(sc_filter_result,\"(?i)block\") OR match(_raw,\"(?i)BLOCK\"))) as \"Web Blocked\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		}
	},
